<?php use InsTickets\Core\View; use InsTickets\Core\Dates; use InsTickets\Core\Auth; use InsTickets\Services\TicketPolicy; use InsTickets\Services\TicketValidation; ?>
<div class="page-heading"><div><span class="eyebrow"><?= View::escape(Dates::code((int) $ticket['id'])) ?></span><h1><?= View::escape($ticket['titulo']) ?></h1></div><?php if (TicketPolicy::classification(Auth::user(), $ticket)): ?><a class="btn btn-primary" href="/tickets/editar?id=<?= (int) $ticket['id'] ?>">Editar datos autorizados</a><?php endif; ?></div>
<div class="card border-0 shadow-sm mb-4"><div class="card-body p-4">
    <div class="d-flex gap-3 flex-wrap mb-3"><span class="badge state-<?= View::escape($ticket['estado']) ?>"><?= View::escape(TicketValidation::STATES[$ticket['estado']]) ?></span><span>Prioridad <?= View::escape(TicketValidation::PRIORITIES[$ticket['prioridad']]) ?></span><span><?= View::escape($ticket['categoria_nombre']) ?><?= !$ticket['categoria_activa'] ? ' (inactiva)' : '' ?></span></div>
    <p class="ticket-text"><?= View::escape($ticket['descripcion']) ?></p>
    <dl class="row mb-0"><dt class="col-md-3">Solicitante</dt><dd class="col-md-9"><?= View::escape($ticket['solicitante_nombre']) ?></dd><dt class="col-md-3">Agente actual</dt><dd class="col-md-9"><?= View::escape($ticket['agente_nombre'] ?? 'Sin asignar') ?></dd><dt class="col-md-3">Creación (El Salvador)</dt><dd class="col-md-9"><?= View::escape(Dates::local($ticket['created_at'])) ?></dd><dt class="col-md-3">Primera respuesta</dt><dd class="col-md-9"><?= View::escape(Dates::local($ticket['first_response_at'])) ?></dd><dt class="col-md-3">Resolución</dt><dd class="col-md-9"><?= View::escape(Dates::local($ticket['resolved_at'])) ?><?= $ticket['resolved_by'] !== null ? ' · ' . View::escape($ticket['resolutor_nombre']) : '' ?></dd><dt class="col-md-3">Cierre</dt><dd class="col-md-9"><?= View::escape(Dates::local($ticket['closed_at'])) ?><?= $ticket['closed_by'] !== null ? ' · ' . View::escape($ticket['cerrador_nombre']) : '' ?></dd></dl>
    <?php if ($ticket['resolution_summary'] !== null): ?><h2 class="h5 mt-3">Resumen de resolución</h2><p class="ticket-text"><?= View::escape($ticket['resolution_summary']) ?></p><?php endif; ?>
</div></div>
<section class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><h2 class="h5">Conversación</h2>
    <?php foreach ($comments['rows'] as $comment): ?><article class="conversation-entry"><strong><?= View::escape($comment['autor_nombre']) ?></strong> · <?= View::escape($comment['autor_rol']) ?><p class="small text-secondary"><?= View::escape(Dates::local($comment['created_at'])) ?></p><p class="ticket-text"><?= View::escape($comment['contenido']) ?></p></article><?php endforeach; ?>
    <?php if ($comments['rows'] === []): ?><p class="text-secondary">Este ticket todavía no tiene comentarios.</p><?php endif; ?>
    <?php $list = $comments; $basePath = '/tickets/detalle'; $paginationPageKey = 'comentarios_pagina'; $paginationParams = ['id' => (int) $ticket['id'], 'historial_pagina' => $history['page']]; require dirname(__DIR__) . '/partials/pagination.php'; ?>
</div></section>
<section class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5">Historial</h2>
    <?php foreach ($history['rows'] as $event): ?><article class="conversation-entry"><strong><?= View::escape($event['tipo']) ?></strong> · <?= View::escape($event['actor_nombre']) ?><p class="small text-secondary"><?= View::escape(Dates::local($event['created_at'])) ?></p><details><summary>Valores del cambio</summary><dl><dt>Anterior</dt><dd><pre><?= View::escape($event['anterior'] === null ? 'Sin valor anterior' : json_encode(json_decode($event['anterior'], true), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></dd><dt>Nuevo</dt><dd><pre><?= View::escape(json_encode(json_decode($event['nuevo'], true), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></dd></dl></details></article><?php endforeach; ?>
    <?php if ($history['rows'] === []): ?><p class="text-secondary">No hay eventos registrados.</p><?php endif; ?>
    <?php $list = $history; $paginationPageKey = 'historial_pagina'; $paginationParams = ['id' => (int) $ticket['id'], 'comentarios_pagina' => $comments['page']]; require dirname(__DIR__) . '/partials/pagination.php'; ?>
</div></section>
<p class="text-secondary mt-4">Las acciones de asignación, atención, comentarios nuevos y transiciones se incorporarán en el incremento 4.</p><a class="btn btn-outline-secondary" href="/tickets/mis">Volver a mis solicitudes</a>
